class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int N = 1 << n;
        int[] sum = new int[N];
        for (int mask = 1; mask < N; ++mask) {
            int lb = mask & -mask;
            int idx = Integer.numberOfTrailingZeros(lb);
            sum[mask] = sum[mask ^ lb] + tasks[idx];
        }
        int[] dp = new int[N];
        int INF = n + 1;
        for (int i = 1; i < N; ++i) dp[i] = INF;
        dp[0] = 0;
        for (int mask = 1; mask < N; ++mask) {
            // iterate submasks of mask
            int sub = mask;
            while (sub > 0) {
                if (sum[sub] <= sessionTime) {
                    dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
                }
                sub = (sub - 1) & mask;
            }
        }
        return dp[N - 1];
    }
}

